:root {
  --re-bg: #f5f3f0;
  --re-card: #ffffff;
  --re-text: #3a3632;
  --re-text-secondary: #8a837a;
  --re-accent: #7B9CB5;
  --re-accent-hover: #6A8BA3;
  --re-accent-light: #D8E6EE;
  --re-border: #d6dce2;
  --re-success: #6a9e6f;
  --re-radius: 14px;
  --re-shadow: 0 2px 10px rgba(58,54,50,0.06);
}

.rhythm-echo {
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  background: var(--re-bg);
  color: var(--re-text);
  max-width: 420px;
  margin: 0 auto;
  padding: 24px 18px 28px;
  border-radius: var(--re-radius);
  box-sizing: border-box;
  text-align: center;
}

.re-header h2 {
  margin: 0 0 4px;
  font-size: 1.3rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.re-subtitle {
  margin: 0 0 16px;
  font-size: 0.85rem;
  color: var(--re-text-secondary);
}

.re-mute-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--re-card);
  border: 1px solid var(--re-border);
  border-radius: 8px;
  margin-bottom: 18px;
  font-size: 0.82rem;
}

.re-mute-label {
  color: var(--re-text-secondary);
}

.re-mute-value {
  font-weight: 600;
}

.re-mute-value.muted { color: #c0392b; }
.re-mute-value.not-muted { color: var(--re-success); }
.re-mute-value.unknown { color: var(--re-text-secondary); }

.re-mute-hint {
  color: #c0392b;
  font-size: 0.78rem;
}

.re-phase {
  font-size: 0.95rem;
  color: var(--re-text-secondary);
  margin-bottom: 14px;
  min-height: 1.4em;
}

.re-play-btn {
  width: 100%;
  padding: 12px 0;
  background: var(--re-accent-light);
  color: var(--re-accent-hover);
  border: none;
  border-radius: var(--re-radius);
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
  margin-bottom: 16px;
}

.re-play-btn:hover:not(:disabled) {
  background: var(--re-accent);
  color: #fff;
}

.re-play-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.re-tap-btn {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: var(--re-accent);
  color: #fff;
  border: none;
  font-size: 1.2rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: var(--re-shadow), 0 4px 16px rgba(123,156,181,0.25);
  transition: transform 0.08s, background 0.15s;
  margin: 10px auto 18px;
  display: block;
}

.re-tap-btn:active {
  transform: scale(0.93);
  background: var(--re-accent-hover);
}

.re-tap-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.re-feedback {
  margin: 10px 0 14px;
  padding: 12px;
  background: var(--re-card);
  border: 1px solid var(--re-border);
  border-radius: var(--re-radius);
  font-size: 0.9rem;
  min-height: 2em;
  display: flex;
  align-items: center;
  justify-content: center;
}

.re-replay-btn {
  width: 100%;
  padding: 11px 0;
  background: var(--re-card);
  color: var(--re-text);
  border: 1.5px solid var(--re-border);
  border-radius: var(--re-radius);
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.2s;
}

.re-replay-btn:hover:not(:disabled) {
  border-color: var(--re-accent);
  background: var(--re-accent-light);
}

.re-status-bar {
  margin-top: 16px;
  padding: 7px 12px;
  background: var(--re-card);
  border: 1px solid var(--re-border);
  border-radius: var(--re-radius);
  font-size: 0.8rem;
  color: var(--re-text-secondary);
}

javascript:
(function() {
  var muteValue = document.getElementById('re-mute-value');
  var muteHint = document.getElementById('re-mute-hint');
  var phaseEl = document.getElementById('re-phase');
  var playBtn = document.getElementById('re-play-btn');
  var tapBtn = document.getElementById('re-tap-btn');
  var feedbackEl = document.getElementById('re-feedback');
  var replayBtn = document.getElementById('re-replay-btn');
  var statusBar = document.getElementById('re-status-bar');

  var audioCtx = null;
  var rhythmIntervals = [];
  var userTapTimes = [];
  var beatCount = 0;
  var gamePhase = 'idle';

  function getAudioContext() {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    return audioCtx;
  }

  function playTone(ctx, time, duration) {
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 440;
    gain.gain.setValueAtTime(0.25, time);
    gain.gain.exponentialRampToValueAtTime(0.001, time + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(time);
    osc.stop(time + duration);
  }

  function generateRhythm() {
    var numBeats = 4 + Math.floor(Math.random() * 3);
    var intervals = [];
    for (var i = 0; i < numBeats - 1; i++) {
      intervals.push(300 + Math.floor(Math.random() * 400));
    }
    return intervals;
  }

  async function playRhythm() {
    if (gamePhase !== 'idle') return;

    rhythmIntervals = generateRhythm();
    beatCount = rhythmIntervals.length + 1;
    userTapTimes = [];
    gamePhase = 'playing';

    var ctx = getAudioContext();
    if (ctx.state === 'suspended') {
      await ctx.resume();
    }

    playBtn.disabled = true;
    phaseEl.textContent = '正在播放节奏…';
    statusBar.textContent = '听好了哦';

    var time = ctx.currentTime + 0.1;
    for (var i = 0; i <= rhythmIntervals.length; i++) {
      playTone(ctx, time, 0.08);
      if (i < rhythmIntervals.length) {
        time += rhythmIntervals[i] / 1000;
      }
    }

    var totalMs = rhythmIntervals.reduce(function(a, b) { return a + b; }, 0) + 300;
    setTimeout(function() {
      gamePhase = 'tapping';
      phaseEl.textContent = '轮到你了！跟着敲';
      tapBtn.style.display = 'block';
      tapBtn.disabled = false;
      statusBar.textContent = '点大按钮敲出节奏';
    }, totalMs);
  }

  function handleTap() {
    if (gamePhase !== 'tapping') return;

    var now = performance.now();
    userTapTimes.push(now);

    var ctx = getAudioContext();
    playTone(ctx, ctx.currentTime, 0.05);

    if (userTapTimes.length === beatCount) {
      finishGame();
    }
  }

  function finishGame() {
    gamePhase = 'done';
    tapBtn.style.display = 'none';
    tapBtn.disabled = true;

    var userIntervals = [];
    for (var i = 1; i < userTapTimes.length; i++) {
      userIntervals.push(userTapTimes[i] - userTapTimes[i - 1]);
    }

    var totalError = 0;
    for (var j = 0; j < rhythmIntervals.length; j++) {
      totalError += Math.abs(userIntervals[j] - rhythmIntervals[j]);
    }
    var avgError = totalError / rhythmIntervals.length;

    var feedback = '';
    if (avgError < 50) {
      feedback = '🎵 太棒了！节奏感真好！';
    } else if (avgError < 100) {
      feedback = '👏 很不错哦，再练练会更准！';
    } else if (avgError < 150) {
      feedback = '😊 有感觉了，慢慢来就好';
    } else {
      feedback = '🌟 有趣的尝试！每个人都有自己的节奏';
    }

    feedbackEl.textContent = feedback;
    phaseEl.textContent = '完成啦';
    replayBtn.style.display = 'block';
    statusBar.textContent = '想再来一次吗';
  }

  function resetGame() {
    gamePhase = 'idle';
    rhythmIntervals = [];
    userTapTimes = [];
    beatCount = 0;

    playBtn.disabled = false;
    tapBtn.style.display = 'none';
    tapBtn.disabled = true;
    replayBtn.style.display = 'none';
    feedbackEl.textContent = '';
    phaseEl.textContent = '点击播放，听听今天的节奏';
    statusBar.textContent = '就绪';
  }

  async function readSystemAudio() {
    try {
      var result = await window.wujian.request('read_volume', {});
      var muted = result.state.muted;
      if (muted === true) {
        muteValue.textContent = '已静音';
        muteValue.className = 're-mute-value muted';
        muteHint.textContent = '请检查系统音量';
      } else if (muted === false) {
        muteValue.textContent = '未静音';
        muteValue.className = 're-mute-value not-muted';
        muteHint.textContent = '';
      } else {
        muteValue.textContent = '未知';
        muteValue.className = 're-mute-value unknown';
        muteHint.textContent = '';
      }
    } catch (e) {
      muteValue.textContent = '未知';
      muteValue.className = 're-mute-value unknown';
      muteHint.textContent = '';
      console.log('read_volume error: ' + e.message);
    }
  }

  playBtn.addEventListener('click', playRhythm);
  tapBtn.addEventListener('click', handleTap);
  replayBtn.addEventListener('click', resetGame);

  readSystemAudio();
})();
